import {readFileSync} from 'node:fs';
import {join} from 'node:path';
import {createServer} from 'node:https';
import {Kernel} from '../../../server/src/kernel.js';
import {PerceptionService} from '../../../server/src/perception.js';
import {SceneLab} from '../../../runtime/src/scene.js';
import {PerceptionSceneBridge} from '../../../runtime/src/perception-bridge.js';
import {DishHearingTurn} from '../../../runtime/src/dish-hearing.js';
import {DishConfirmationHost} from '../../../runtime/src/dish-confirmation.js';
import {compileDishSemanticProposal} from '../../../runtime/src/dish-semantics.js';
import {createSceneServer} from '../../../runtime/src/scene-server.js';
import {createProtectedPreview} from '../../../runtime/src/protected-preview.js';
// Controlled ASR/model/player. Only TLS, runtime and SQLite are real here.
const dir=process.argv[2],lab=new SceneLab(join(dir,'core.sqlite'),join(dir,'sink.sqlite'));
const kernel=new Kernel(join(dir,'legacy')),subjects={companion:kernel.createSubject('test',{name:'companion'}).id,work:kernel.createSubject('test',{name:'work'}).id};
for(const id of Object.values(subjects))kernel.mount('test',id,'sense.hearing');
const service=new PerceptionService(kernel,{processor:{capabilities:async()=>({hearing:{available:true,language:'zh'}}),process:async()=>({text:'刚才这个能给我讲明白吗',engine:'controlled-fixture',model:'not-real-ASR',realProcessing:true}),cancel(){}}});
const bridge=new PerceptionSceneBridge(lab,{kernel,service,subjects,ownerId:'test',exclusiveOwner:true,ttlMs:60000});
const context=lab.captureSenseContext(),sessionId='meal',dishId='soup',taskId='meal-task';
lab.installDishCatalog({schema:'synthetic-dish-catalog.v1',catalogId:'menu',items:[{dishId,name:'合成汤',description:'显式确认后同一道菜的合成说明',imageRef:'synthetic-soup'}]});
lab.createDishSession({sessionId,taskId,catalogId:'menu',context});
const audio=Buffer.alloc(3244);audio.write('RIFF');audio.writeUInt32LE(audio.length-8,4);audio.write('WAVEfmt ',8);audio.writeUInt32LE(16,16);audio.writeUInt16LE(1,20);audio.writeUInt16LE(1,22);audio.writeUInt32LE(16000,24);audio.writeUInt32LE(32000,28);audio.writeUInt16LE(2,32);audio.writeUInt16LE(16,34);audio.write('data',36);audio.writeUInt32LE(3200,40);
const narrator=lab.createDishNarration({synthesizer:{synthesize:async()=>({audio})},player:{play:async()=>{},stop:async()=>{}}});
await narrator.start({sessionId,dishId,expectedRevision:1});
const turn=new DishHearingTurn(lab,{bridge,narrator,sessionId,interpreter:{modelId:'controlled-model-not-real',interpret:async()=>({modelId:'controlled-model-not-real',proposal:compileDishSemanticProposal({kind:'explain',target:'current-dish'})})}});
const confirmation=new DishConfirmationHost(turn);
const proposal=await confirmation.ingest({expectedRevision:2,context,media:{mimeType:'audio/wav',base64:audio.toString('base64')},language:'zh'});
if(proposal.state!=='pending'||lab.readDish({sessionId}).focus.view!=='none')throw Error('fixture_not_pending');
const upstream=createSceneServer(lab);await new Promise(resolve=>upstream.listen(0,'127.0.0.1',resolve));let gate;
const server=createServer({key:readFileSync(join(dir,'key.pem')),cert:readFileSync(join(dir,'cert.pem'))},(req,res)=>gate(req,res));await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));
const origin=`https://127.0.0.1:${server.address().port}`;
gate=createProtectedPreview({origin,invitation:'synthetic-dish-invitation-aaaaaaaaaaaaaaaaaaaaa',upstream:`http://127.0.0.1:${upstream.address().port}`,dishConfirmation:confirmation});
console.log(JSON.stringify({origin,sessionId,dishId,taskId,synthetic:true,asr:'controlled-fixture',model:'controlled-fixture',player:'controlled-fixture'}));
process.on('SIGTERM',async()=>{await confirmation.close();gate.close();server.close(()=>upstream.close(()=>{bridge.close();service.close();kernel.close();lab.close();process.exit(0);}));});
